//! Verify a browser-produced reconstruction V3 Borsh bundle.
//!
//! This narrow CLI is used by the WASM/Rust compatibility regression. It
//! accepts no secret material: the statement and proof are public protocol
//! outputs generated by the browser client.

use std::{env, process::ExitCode};

use borsh::BorshDeserialize;
use poker_protocol::{
    crypto::DefaultCurve,
    zk_shuffle::{
        reconstruction::{
            ReconstructProofV3, ReconstructionV3Statement, RECONSTRUCTION_V3_PROOF_LABEL,
        },
        transcript_ext::{CryptoTranscript, FiatShamirTranscript},
    },
};

fn decode_hex_argument(name: &str, index: usize) -> Result<Vec<u8>, String> {
    let value = env::args().nth(index).ok_or_else(|| {
        "usage: verify_reconstruction_v3_borsh <statement_borsh_hex> <proof_borsh_hex>".to_owned()
    })?;
    hex::decode(value).map_err(|error| format!("invalid {name} hex: {error}"))
}

fn run() -> Result<(), String> {
    let statement_bytes = decode_hex_argument("statement", 1)?;
    let proof_bytes = decode_hex_argument("proof", 2)?;
    let statement = ReconstructionV3Statement::<DefaultCurve>::try_from_slice(&statement_bytes)
        .map_err(|error| format!("decode reconstruction V3 statement: {error}"))?;
    let proof = ReconstructProofV3::<DefaultCurve>::try_from_slice(&proof_bytes)
        .map_err(|error| format!("decode reconstruction V3 proof: {error}"))?;
    statement
        .validate()
        .map_err(|error| format!("validate reconstruction V3 statement: {error:?}"))?;
    let mut transcript = FiatShamirTranscript::new(RECONSTRUCTION_V3_PROOF_LABEL);
    proof
        .verify(&statement, &mut transcript)
        .map_err(|error| format!("verify reconstruction V3 proof: {error:?}"))?;
    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => {
            println!("browser reconstruction V3 Borsh bundle verified");
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("browser reconstruction V3 Borsh bundle rejected: {error}");
            ExitCode::FAILURE
        }
    }
}
